From 0dc16ef4f6c2708407fab6d141908d46a3b737bc Mon Sep 17 00:00:00 2001
From: Filipe Manana <fdmanana@suse.com>
Date: Wed, 14 Apr 2021 14:05:26 +0100
Subject: [PATCH] btrfs: zoned: fix unpaired block group unfreeze during device
 replace

When doing a device replace on a zoned filesystem, if we find a block
group with ->to_copy == 0, we jump to the label 'done', which will result
in later calling btrfs_unfreeze_block_group(), even though at this point
we never called btrfs_freeze_block_group().

Since at this point we have neither turned the block group to RO mode nor
made any progress, we don't need to jump to the label 'done'. So fix this
by jumping instead to the label 'skip' and dropping our reference on the
block group before the jump.

Fixes: 78ce9fc269af6e ("btrfs: zoned: mark block groups to copy for device-replace")
CC: stable@vger.kernel.org # 5.12
Reviewed-by: Johannes Thumshirn <johannes.thumshirn@wdc.com>
Signed-off-by: Filipe Manana <fdmanana@suse.com>
Reviewed-by: David Sterba <dsterba@suse.com>
Signed-off-by: David Sterba <dsterba@suse.com>

diff --git a/fs/btrfs/scrub.c b/fs/btrfs/scrub.c
index 17e49caad1f9..485cda3eb8d7 100644
--- a/fs/btrfs/scrub.c
+++ b/fs/btrfs/scrub.c
@@ -3674,8 +3674,8 @@ int scrub_enumerate_chunks(struct scrub_ctx *sctx,
 			spin_lock(&cache->lock);
 			if (!cache->to_copy) {
 				spin_unlock(&cache->lock);
-				ro_set = 0;
-				goto done;
+				btrfs_put_block_group(cache);
+				goto skip;
 			}
 			spin_unlock(&cache->lock);
 		}
@@ -3833,7 +3833,6 @@ int scrub_enumerate_chunks(struct scrub_ctx *sctx,
 						      cache, found_key.offset))
 			ro_set = 0;

-done:
 		down_write(&dev_replace->rwsem);
 		dev_replace->cursor_left = dev_replace->cursor_right;
 		dev_replace->item_needs_writeback = 1;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug occurs because during a device replace operation, the code incorrectly jumps to the 'done' label when it encounters a block group with `->to_copy == 0`. This leads to a call to `btrfs_unfreeze_block_group()` without a prior call to `btrfs_freeze_block_group()`, resulting in an unpaired unfreeze operation that can cause inconsistencies in the filesystem state.

        Commit message:
        btrfs: zoned: fix unpaired block group unfreeze during device
 replace

When doing a device replace on a zoned filesystem, if we find a block
group with ->to_copy == 0, we jump to the label 'done', which will result
in later calling btrfs_unfreeze_block_group(), even though at this point
we never called btrfs_freeze_block_group().

Since at this point we have neither turned the block group to RO mode nor
made any progress, we don't need to jump to the label 'done'. So fix this
by jumping instead to the label 'skip' and dropping our reference on the
block group before the jump.

Fixes: 78ce9fc269af6e ("btrfs: zoned: mark block groups to copy for device-replace")
CC: stable@vger.kernel.org # 5.12
Reviewed-by: Johannes Thumshirn <johannes.thumshirn@wdc.com>
Signed-off-by: Filipe Manana <fdmanana@suse.com>
Reviewed-by: David Sterba <dsterba@suse.com>
Signed-off-by: David Sterba <dsterba@suse.com>  

        Patch:

 static noinline_for_stack
 int scrub_enumerate_chunks(struct scrub_ctx *sctx,
 			   struct btrfs_device *scrub_dev, u64 start, u64 end)
 {
 	struct btrfs_dev_extent *dev_extent = NULL;
 	struct btrfs_path *path;
 	struct btrfs_fs_info *fs_info = sctx->fs_info;
 	struct btrfs_root *root = fs_info->dev_root;
 	u64 length;
 	u64 chunk_offset;
 	int ret = 0;
 	int ro_set;
 	int slot;
 	struct extent_buffer *l;
 	struct btrfs_key key;
 	struct btrfs_key found_key;
 	struct btrfs_block_group *cache;
 	struct btrfs_dev_replace *dev_replace = &fs_info->dev_replace;

 	path = btrfs_alloc_path();
 	if (!path)
 		return -ENOMEM;

 	path->reada = READA_FORWARD;
 	path->search_commit_root = 1;
 	path->skip_locking = 1;

 	key.objectid = scrub_dev->devid;
 	key.offset = 0ull;
 	key.type = BTRFS_DEV_EXTENT_KEY;

 	while (1) {
 		ret = btrfs_search_slot(NULL, root, &key, path, 0, 0);
 		if (ret < 0)
 			break;
 		if (ret > 0) {
 			if (path->slots[0] >=
 			    btrfs_header_nritems(path->nodes[0])) {
 				ret = btrfs_next_leaf(root, path);
 				if (ret < 0)
 					break;
 				if (ret > 0) {
 					ret = 0;
 					break;
 				}
 			} else {
 				ret = 0;
 			}
 		}

 		l = path->nodes[0];
 		slot = path->slots[0];

 		btrfs_item_key_to_cpu(l, &found_key, slot);

 		if (found_key.objectid != scrub_dev->devid)
 			break;

 		if (found_key.type != BTRFS_DEV_EXTENT_KEY)
 			break;

 		if (found_key.offset >= end)
 			break;

 		if (found_key.offset < key.offset)
 			break;

 		dev_extent = btrfs_item_ptr(l, slot, struct btrfs_dev_extent);
 		length = btrfs_dev_extent_length(l, dev_extent);

 		if (found_key.offset + length <= start)
 			goto skip;

 		chunk_offset = btrfs_dev_extent_chunk_offset(l, dev_extent);

 		/*
 		 * get a reference on the corresponding block group to prevent
 		 * the chunk from going away while we scrub it
 		 */
 		cache = btrfs_lookup_block_group(fs_info, chunk_offset);

 		/* some chunks are removed but not committed to disk yet,
 		 * continue scrubbing */
 		if (!cache)
 			goto skip;

 		if (sctx->is_dev_replace && btrfs_is_zoned(fs_info)) {
 			spin_lock(&cache->lock);
 			if (!cache->to_copy) {
 				spin_unlock(&cache->lock);
-				ro_set = 0;
-				goto done;
+				btrfs_put_block_group(cache);
+				goto skip;
 			}
 			spin_unlock(&cache->lock);
 		}

 		/*
 		 * Make sure that while we are scrubbing the corresponding block
 		 * group doesn't get its logical address and its device extents
 		 * reused for another block group, which can possibly be of a
 		 * different type and different profile. We do this to prevent
 		 * false error detections and crashes due to bogus attempts to
 		 * repair extents.
 		 */
 		spin_lock(&cache->lock);
 		if (cache->removed) {
 			spin_unlock(&cache->lock);
 			btrfs_put_block_group(cache);
 			goto skip;
 		}
 		btrfs_freeze_block_group(cache);
 		spin_unlock(&cache->lock);

 		/*
 		 * we need call btrfs_inc_block_group_ro() with scrubs_paused,
 		 * to avoid deadlock caused by:
 		 * btrfs_inc_block_group_ro()
 		 * -> btrfs_wait_for_commit()
 		 * -> btrfs_commit_transaction()
 		 * -> btrfs_scrub_pause()
 		 */
 		scrub_pause_on(fs_info);

 		/*
 		 * Don't do chunk preallocation for scrub.
 		 *
 		 * This is especially important for SYSTEM bgs, or we can hit
 		 * -EFBIG from btrfs_finish_chunk_alloc() like:
 		 * 1. The only SYSTEM bg is marked RO.
 		 *    Since SYSTEM bg is small, that's pretty common.
 		 * 2. New SYSTEM bg will be allocated
 		 *    Due to regular version will allocate new chunk.
 		 * 3. New SYSTEM bg is empty and will get cleaned up
 		 *    Before cleanup really happens, it's marked RO again.
 		 * 4. Empty SYSTEM bg get scrubbed
 		 *    We go back to 2.
 		 *
 		 * This can easily boost the amount of SYSTEM chunks if cleaner
 		 * thread can't be triggered fast enough, and use up all space
 		 * of btrfs_super_block::sys_chunk_array
 		 *
 		 * While for dev replace, we need to try our best to mark block
 		 * group RO, to prevent race between:
 		 * - Write duplication
 		 *   Contains latest data
 		 * - Scrub copy
 		 *   Contains data from commit tree
 		 *
 		 * If target block group is not marked RO, nocow writes can
 		 * be overwritten by scrub copy, causing data corruption.
 		 * So for dev-replace, it's not allowed to continue if a block
 		 * group is not RO.
 		 */
 		ret = btrfs_inc_block_group_ro(cache, sctx->is_dev_replace);
 		if (!ret && sctx->is_dev_replace) {
 			ret = finish_extent_writes_for_zoned(root, cache);
 			if (ret) {
 				btrfs_dec_block_group_ro(cache);
 				scrub_pause_off(fs_info);
 				btrfs_put_block_group(cache);
 				break;
 			}
 		}

 		if (ret == 0) {
 			ro_set = 1;
 		} else if (ret == -ENOSPC && !sctx->is_dev_replace) {
 			/*
 			 * btrfs_inc_block_group_ro return -ENOSPC when it
 			 * failed in creating new chunk for metadata.
 			 * It is not a problem for scrub, because
 			 * metadata are always cowed, and our scrub paused
 			 * commit_transactions.
 			 */
 			ro_set = 0;
 		} else if (ret == -ETXTBSY) {
 			btrfs_warn(fs_info,
 		   "skipping scrub of block group %llu due to active swapfile",
 				   cache->start);
 			scrub_pause_off(fs_info);
 			ret = 0;
 			goto skip_unfreeze;
 		} else {
 			btrfs_warn(fs_info,
 				   "failed setting block group ro: %d", ret);
 			btrfs_unfreeze_block_group(cache);
 			btrfs_put_block_group(cache);
 			scrub_pause_off(fs_info);
 			break;
 		}

 		/*
 		 * Now the target block is marked RO, wait for nocow writes to
 		 * finish before dev-replace.
 		 * COW is fine, as COW never overwrites extents in commit tree.
 		 */
 		if (sctx->is_dev_replace) {
 			btrfs_wait_nocow_writers(cache);
 			btrfs_wait_ordered_roots(fs_info, U64_MAX, cache->start,
 					cache->length);
 		}

 		scrub_pause_off(fs_info);
 		down_write(&dev_replace->rwsem);
 		dev_replace->cursor_right = found_key.offset + length;
 		dev_replace->cursor_left = found_key.offset;
 		dev_replace->item_needs_writeback = 1;
 		up_write(&dev_replace->rwsem);

 		ret = scrub_chunk(sctx, scrub_dev, chunk_offset, length,
 				  found_key.offset, cache);

 		/*
 		 * flush, submit all pending read and write bios, afterwards
 		 * wait for them.
 		 * Note that in the dev replace case, a read request causes
 		 * write requests that are submitted in the read completion
 		 * worker. Therefore in the current situation, it is required
 		 * that all write requests are flushed, so that all read and
 		 * write requests are really completed when bios_in_flight
 		 * changes to 0.
 		 */
 		sctx->flush_all_writes = true;
 		scrub_submit(sctx);
 		mutex_lock(&sctx->wr_lock);
 		scrub_wr_submit(sctx);
 		mutex_unlock(&sctx->wr_lock);

 		wait_event(sctx->list_wait,
 			   atomic_read(&sctx->bios_in_flight) == 0);

 		scrub_pause_on(fs_info);

 		/*
 		 * must be called before we decrease @scrub_paused.
 		 * make sure we don't block transaction commit while
 		 * we are waiting pending workers finished.
 		 */
 		wait_event(sctx->list_wait,
 			   atomic_read(&sctx->workers_pending) == 0);
 		sctx->flush_all_writes = false;

 		scrub_pause_off(fs_info);

 		if (sctx->is_dev_replace &&
 		    !btrfs_finish_block_group_to_copy(dev_replace->srcdev,
 						      cache, found_key.offset))
 			ro_set = 0;

-done:
 		down_write(&dev_replace->rwsem);
 		dev_replace->cursor_left = dev_replace->cursor_right;
 		dev_replace->item_needs_writeback = 1;
 		up_write(&dev_replace->rwsem);

 		if (ro_set)
 			btrfs_dec_block_group_ro(cache);

 		/*
 		 * We might have prevented the cleaner kthread from deleting
 		 * this block group if it was already unused because we raced
 		 * and set it to RO mode first. So add it back to the unused
 		 * list, otherwise it might not ever be deleted unless a manual
 		 * balance is triggered or it becomes used and unused again.
 		 */
 		spin_lock(&cache->lock);
 		if (!cache->removed && !cache->ro && cache->reserved == 0 &&
 		    cache->used == 0) {
 			spin_unlock(&cache->lock);
 			if (btrfs_test_opt(fs_info, DISCARD_ASYNC))
 				btrfs_discard_queue_work(&fs_info->discard_ctl,
 							 cache);
 			else
 				btrfs_mark_bg_unused(cache);
 		} else {
 			spin_unlock(&cache->lock);
 		}
 skip_unfreeze:
 		btrfs_unfreeze_block_group(cache);
 		btrfs_put_block_group(cache);
 		if (ret)
 			break;
 		if (sctx->is_dev_replace &&
 		    atomic64_read(&dev_replace->num_write_errors) > 0) {
 			ret = -EIO;
 			break;
 		}
 		if (sctx->stat.malloc_errors > 0) {
 			ret = -ENOMEM;
 			break;
 		}
 skip:
 		key.offset = found_key.offset + length;
 		btrfs_release_path(path);
 	}

 	btrfs_free_path(path);

 	return ret;
 }



